import pytest


def age_at(born: int, now: int) -> int:
    """Whole years between a birth year and a given current year.

    The current year is passed in explicitly; this function never reads the clock.
    """
    return now - born


def test_age_at_later_year() -> None:
    assert age_at(1990, 2024) == 34


def test_age_at_same_year_is_zero() -> None:
    assert age_at(2000, 2000) == 0


def test_age_at_one_year_apart() -> None:
    assert age_at(1999, 2000) == 1


def test_age_at_is_deterministic() -> None:
    assert age_at(1980, 2020) == age_at(1980, 2020)
